<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
import Shopping29CmMedia from '../Shopping29CmMedia.vue'
import { shopping29cmMediaSource, shopping29cmProductMedia, shopping29cmProductTone } from '../shopping-29cm-media'

const props = defineProps(SHOPPING_OPERATION_PAGE_PROPS)
const emit = defineEmits(SHOPPING_OPERATION_PAGE_EVENTS)
const localize = (zh, en) => localizeOperationPage(props.languageBase, zh, en)
const itemTitle = (item) => item?.title || item?.product?.title || localize('未命名物件', 'Untitled object')
const itemImage = (item) => props.productImageUrl(item?.product || item || {}) || shopping29cmMediaSource(shopping29cmProductMedia(item?.productId || item?.product?.id || item?.id, 'main'))
const itemTone = (item) => shopping29cmProductTone(item?.productId || item?.product?.id || '')
</script>

<template>
  <main class="cm-ops" :data-page="pageKey" data-testid="shopping-store-operation-page">
    <header class="cm-opbar"><button type="button" class="cm-op-back" @click="emit('back')"><i class="fas fa-arrow-left" aria-hidden="true"></i></button><div><span>29CM / SEOUL</span><strong>{{ serviceLabel || '29CM' }}</strong></div><nav><button type="button" data-testid="shopping-open-service" @click="emit('open-service')">CARE</button><button type="button" @click="emit('open-orders')">ARCHIVE</button><button type="button" @click="emit('open-cart')">BAG <b v-if="cartQuantity">{{ cartQuantity }}</b></button></nav></header>

    <section v-if="pageKey === 'cart'" id="shopping-cart" class="cm-bag"><header class="cm-op-intro"><span>BAG / CONSIDERED OBJECTS</span><h1>{{ localize('把选择放在一起，再决定。', 'Keep the objects together before deciding.') }}</h1><p>{{ localize('选品袋是一张编辑清单，不是催促结算的倒计时。', 'The bag is an editorial checklist, not a checkout countdown.') }}</p></header><div v-if="!cartItems.length" class="cm-op-empty"><Shopping29CmMedia :src="''" alt="" eyebrow="BAG / EMPTY" label="—" tone="paper" role="state" icon="fas fa-bag-shopping" /><div><span>SELECTION / 00</span><h2>{{ localize('这里还没有被留下的物件。', 'Nothing has been kept here yet.') }}</h2><button type="button" @click="emit('back')">{{ localize('回到本期', 'RETURN TO ISSUE') }}</button></div></div><div v-else class="cm-bag-layout"><section class="cm-line-list"><article v-for="(line, index) in cartItems" :key="line.productId" class="cm-bag-line"><span class="cm-line-number">{{ String(index + 1).padStart(2, '0') }}</span><Shopping29CmMedia :src="itemImage(line)" :alt="itemTitle(line)" :label="'OBJECT ' + String(index + 1).padStart(2, '0')" :tone="itemTone(line)" icon="fas fa-cube" /><div><small>OBJECT NOTE</small><h2>{{ itemTitle(line) }}</h2><strong>{{ formatOrderItemSubtotal({ ...line, unitPriceCents: line.product?.priceCents || line.unitPriceCents, currency: line.currency }) }}</strong><div class="cm-qty"><button type="button" :aria-label="localize('减少数量', 'Decrease quantity')" @click="emit('update-quantity', line.productId, -1)">−</button><span>{{ line.quantity }}</span><button type="button" :aria-label="localize('增加数量', 'Increase quantity')" @click="emit('update-quantity', line.productId, 1)">+</button></div></div></article></section><aside class="cm-bag-summary"><span>REVIEW / {{ cartQuantity }} OBJECTS</span><strong>{{ cartTotalLabel }}</strong><blockquote>{{ localize('真正留下的，应该经得起重复观看。', 'What remains should reward repeated attention.') }}</blockquote><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled', $event.target.checked)" /> {{ localize('礼赠编辑', 'GIFT EDIT') }}</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId', $event.target.value)"><option value="">{{ localize('手动填写收件人', 'MANUAL RECIPIENT') }}</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" :placeholder="localize('收件人姓名', 'RECIPIENT NAME')" @input="emit('update:giftRecipientName', $event.target.value)" /><button type="button" data-testid="shopping-checkout" @click="emit('checkout')">{{ localize('进入最终编辑', 'CREATE FINAL EDIT') }} <i class="fas fa-arrow-right" aria-hidden="true"></i></button></aside></div></section>

    <section v-else-if="pageKey === 'orders'" id="shopping-orders" class="cm-archive"><header class="cm-op-intro"><div><span>ARCHIVE / PURCHASED OBJECTS</span><h1>{{ localize('选择留下的记录。', 'An archive of chosen objects.') }}</h1></div><button type="button" class="cm-inline-link" @click="emit('open-logistics')">DELIVERY JOURNAL →</button></header><div v-if="!orders.length" class="cm-op-empty"><Shopping29CmMedia :src="''" alt="" eyebrow="ARCHIVE / EMPTY" label="—" tone="paper" role="state" icon="fas fa-folder-open" /><div><span>ARCHIVE / 00</span><h2>{{ localize('购买完成后，记录会从这里开始。', 'The record begins here after purchase.') }}</h2><button type="button" @click="emit('back')">{{ localize('回到本期', 'RETURN TO ISSUE') }}</button></div></div><div v-else class="cm-archive-list"><article v-for="(order, index) in orders" :key="order.id" :data-testid="'shopping-order-' + order.id"><div class="cm-archive-number">{{ String(index + 1).padStart(2, '0') }}</div><div class="cm-archive-copy"><span>{{ formatLogisticsDate(order.createdAt) }} / {{ order.itemCount }} OBJECTS</span><h2>{{ order.items.map(item => item.title).join(' / ') }}</h2><p>{{ formatOrderTotal(order) }}</p><div><em>{{ orderStatusLabel(order.status) }}</em><button type="button" :data-testid="'shopping-open-order-detail-' + order.id" @click="emit('open-order', order.id)">OPEN DOSSIER →</button><button type="button" @click="emit('delete-order', order.id)">DELETE</button></div></div></article></div></section>

