    <section v-else-if="selectedOrder" class="cm-dossier" data-testid="shopping-order-detail-panel"><header class="cm-op-intro cm-dossier-head"><button type="button" @click="emit('close-order')">← ARCHIVE</button><span>OBJECT DOSSIER / {{ selectedOrder.id }}</span><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header><section class="cm-dossier-cover"><div><span>TOTAL VALUE</span><strong data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</strong></div><h1>{{ selectedOrder.items.map(item => item.title).join(' / ') }}</h1><span>{{ selectedOrder.itemCount }} OBJECTS</span></section><section class="cm-dossier-items"><article v-for="(item, index) in selectedOrder.items" :key="item.id" :data-testid="'shopping-order-detail-item-' + item.productId"><span>{{ String(index + 1).padStart(2, '0') }}</span><Shopping29CmMedia :src="itemImage(item)" :alt="itemTitle(item)" :label="'OBJECT ' + String(index + 1).padStart(2, '0')" :tone="itemTone(item)" icon="fas fa-cube" /><div><h2>{{ item.title }}</h2><p>{{ item.quantity }} × {{ formatOrderItemSubtotal({ ...item, quantity: 1 }) }}</p><strong>{{ formatOrderItemSubtotal(item) }}</strong></div></article></section><section class="cm-dossier-timeline" data-testid="shopping-order-detail-timeline"><span>DELIVERY NOTES</span><article v-for="event in selectedOrder.events || []" :key="event.id" :data-testid="'shopping-order-detail-event-' + event.id"><time>{{ formatLogisticsDate(event.createdAt) }}</time><strong>{{ logisticsEventTypeLabel(event.type) }}</strong><p>{{ event.summary || event.title }}</p></article><div v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">NO RECORDED DELIVERY NOTES</div></section><footer class="cm-dossier-actions"><button type="button" data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order', selectedOrder.id)">COMPLETE ARCHIVE</button><button type="button" data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order', selectedOrder.id)">CANCEL</button><button type="button" data-testid="shopping-order-detail-delete" @click="emit('delete-order', selectedOrder.id)">DELETE RECORD</button></footer></section>
